// ─────────────────────────────────────────────────────────────
// CLEAN, DEDUPE & SCORE ADS
// Input : raw items from Apify's Facebook Ads Library Scraper
// Output: one clean item per ad, sorted by performanceScore
//
// Meta hides spend/reach for normal (non-political) ads in India,
// so we score on three proxies Meta *does* leak:
//   1. impressionRank – the Ad Library URL is sorted by total impressions,
//                       so result order = Meta's own impression ranking
//   2. daysActive     – advertisers kill losing ads fast; survivors pay back
//   3. scale          – how many live ads reuse the same copy, or how many
//                       versions Meta groups under one ad (collationCount):
//                       the team is putting more money behind that concept
// ─────────────────────────────────────────────────────────────
const cfg = $('Config').first().json;
const brand = String(cfg.brandFilter || '').toLowerCase().trim();
const capDays = Number(cfg.longevityCapDays) || 90;
const nowSec = Date.now() / 1000;

const isPlaceholder = (s) => !s || /\{\{[^}]*\}\}/.test(String(s)); // {{product.name}} etc. in DCO ads
const tidy = (s) => String(s || '').replace(/\s+/g, ' ').trim();

// Facebook video URLs carry a base64 "efg" param with the asset id + duration
function decodeEfg(url) {
  try {
    const m = String(url || '').match(/[?&]efg=([^&]+)/);
    if (!m) return {};
    const j = JSON.parse(Buffer.from(decodeURIComponent(m[1]), 'base64').toString('utf8'));
    return { assetId: j.xpv_asset_id, durationSec: j.duration_s };
  } catch (e) {
    return {};
  }
}

function detectLanguage(t) {
  if (/[ಀ-೿]/.test(t)) return 'Kannada';
  if (/[ఀ-౿]/.test(t)) return 'Telugu';
  if (/[஀-௿]/.test(t)) return 'Tamil';
  if (/[ঀ-৿]/.test(t)) return 'Bengali';
  if (/[઀-૿]/.test(t)) return 'Gujarati';
  if (/[ഀ-ൿ]/.test(t)) return 'Malayalam';
  if (/[਀-੿]/.test(t)) return 'Punjabi';
  if (/[଀-୿]/.test(t)) return 'Odia';
  if (/[ऀ-ॿ]/.test(t)) return /(करा|आणि|सोबत|मध्ये|आजच)/.test(t) ? 'Marathi' : 'Hindi';
  if (/\b(korun|apnake|bujhiye|parben|theke|korlei)\b/i.test(t)) return 'Bengali (Roman script)';
  if (/\b(karo|mein|sirf|seekho|bolo|hai|aap|nahi|kaise)\b/i.test(t)) return 'Hinglish';
  return 'English';
}

function firstSentence(t) {
  const m = String(t || '').match(/^(.+?[.!?।])(\s|$)/);
  return tidy(m ? m[1] : String(t || '').slice(0, 120));
}

// Same primary text = same concept (DCO ads reuse copy with different videos)
function conceptKey(text) {
  return String(text || '')
    .toLowerCase()
    .normalize('NFKC')
    .replace(/[^\p{L}\p{M}\p{N}\s]/gu, '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 80);
}

function toSec(v, formatted) {
  const n = Number(v);
  if (n > 1e12) return n / 1000; // milliseconds
  if (n > 1e8) return n;         // seconds
  const p = Date.parse(formatted || v);
  return isNaN(p) ? null : p / 1000;
}

// ── 1. sanity-check the scrape ───────────────────────────────
const raw = $input.all().map((it) => it.json || {});
const apifyError = raw.find((r) => r.error && !r.adArchiveID && !r.adArchiveId);
const rows = raw.filter((r) => r.adArchiveID || r.adArchiveId);
if (!rows.length) {
  const why = apifyError ? ` Apify said: ${JSON.stringify(apifyError.error).slice(0, 300)}` : '';
  throw new Error('Apify returned no ads. Check the Apify credential, your free credit, and that adLibraryUrl in Config opens in a browser.' + why);
}

// ── 2. filter to the brand, drop duplicates ──────────────────
const seenIds = new Set();
const kept = rows.filter((r) => {
  const id = String(r.adArchiveID || r.adArchiveId);
  if (seenIds.has(id)) return false;
  seenIds.add(id);
  const page = String(r.pageName || (r.snapshot && r.snapshot.pageName) || '').toLowerCase();
  return (!brand || page.includes(brand)) && r.isActive !== false;
});
if (!kept.length) {
  const pages = [...new Set(rows.map((r) => r.pageName || (r.snapshot && r.snapshot.pageName)).filter(Boolean))].slice(0, 5);
  throw new Error(`No ads matched brandFilter "${brand}". Pages found: ${pages.join(', ') || 'none'}. Fix brandFilter in Config.`);
}

// ── 3. normalise each ad ─────────────────────────────────────
const ads = kept.map((r, idx) => {
  const s = r.snapshot || {};
  const cards = Array.isArray(s.cards) && s.cards.length
    ? s.cards
    : [{ title: s.title, body: s.body && s.body.text, ctaText: s.ctaText, ctaType: s.ctaType, linkUrl: s.linkUrl }];
  const c0 = cards.find((c) => !isPlaceholder(c.body)) || cards[0] || {};

  const headline = tidy([c0.title, s.title].find((t) => !isPlaceholder(t)) || '');
  const primaryText = tidy([c0.body, s.body && s.body.text].find((t) => !isPlaceholder(t)) || '');

  // unique creatives inside this (often DCO) ad
  const seen = new Set();
  const videos = [];
  for (const c of [...cards, ...(s.videos || [])]) {
    const url = c.videoSdUrl || c.videoHdUrl; // SD first: smaller, plenty for analysis
    if (!url) continue;
    const meta = decodeEfg(url);
    const key = meta.assetId || url.split('?')[0];
    if (seen.has(key)) continue;
    seen.add(key);
    videos.push({ url, key, thumb: c.videoPreviewImageUrl, ...meta });
  }
  const images = [...new Set([
    ...cards.map((c) => c.originalImageUrl || c.resizedImageUrl),
    ...(s.images || []).map((i) => i.originalImageUrl || i.resizedImageUrl),
  ].filter(Boolean))];

  const start = toSec(r.startDate, r.startDateFormatted) || nowSec;
  const endRaw = toSec(r.endDate, r.endDateFormatted);
  const end = endRaw && endRaw <= nowSec + 86400 ? endRaw : nowSec;
  const link = c0.linkUrl || s.linkUrl || '';
  const adId = String(r.adArchiveID || r.adArchiveId);
  const daysActive = Math.max(1, Math.round((end - start) / 86400));
  const creativeKey = (videos[0] && String(videos[0].key)) || (images[0] && images[0].split('?')[0]) || `copy:${conceptKey(primaryText || headline)}`;

  return {
    adId,
    adLibraryLink: `https://www.facebook.com/ads/library/?id=${adId}`,
    pageName: r.pageName || s.pageName || '',
    impressionRank: idx + 1,
    startDate: new Date(start * 1000).toISOString().slice(0, 10),
    daysActive,
    maturity: daysActive < 7 ? 'new (unproven)' : daysActive < 30 ? 'scaling' : 'proven',
    collationCount: Number(r.collationCount) || 1,
    language: detectLanguage(`${headline} ${primaryText}`),
    headline,
    primaryText,
    copyHook: firstSentence(primaryText),
    ctaButton: c0.ctaText || s.ctaText || '',
    ctaType: c0.ctaType || s.ctaType || '',
    store: /itunes|apps\.apple/.test(link) ? 'iOS' : /play\.google/.test(link) ? 'Android' : 'Web/other',
    platforms: (Array.isArray(r.publisherPlatform) ? r.publisherPlatform : []).join(', '),
    displayFormat: s.displayFormat || '',
    mediaType: videos.length ? 'video' : images.length ? 'image' : 'text',
    creativeVariants: videos.length || images.length || 1,
    videoDurationSec: videos[0] ? videos[0].durationSec ?? null : null,
    videoUrl: videos[0] ? videos[0].url : '',
    imageUrl: images[0] || (videos[0] && videos[0].thumb) || '',
    creativeKey,
    conceptKey: conceptKey(primaryText || headline),
  };
});

// ── 4. concept-level stats + performance score (0–100) ───────
const concepts = {};
for (const a of ads) (concepts[a.conceptKey] = concepts[a.conceptKey] || []).push(a);
for (const a of ads) a.scaleUnits = Math.max(concepts[a.conceptKey].length, a.collationCount);
const maxScale = Math.max(...ads.map((a) => a.scaleUnits));
const N = ads.length;

for (const a of ads) {
  const g = concepts[a.conceptKey];
  a.adsInConcept = g.length;
  a.conceptLabel = `${a.language}: ${g[0].headline || g[0].copyHook}`.slice(0, 90);
  a.rankScore = Math.round(N > 1 ? ((N - a.impressionRank) / (N - 1)) * 100 : 100);
  a.longevityScore = Math.round((Math.min(a.daysActive, capDays) / capDays) * 100);
  a.scaleScore = Math.round((a.scaleUnits / maxScale) * 100);
  a.performanceScore = Math.round(0.5 * a.rankScore + 0.35 * a.longevityScore + 0.15 * a.scaleScore);
}

ads.sort((x, y) => y.performanceScore - x.performanceScore || x.impressionRank - y.impressionRank);
return ads.map((a) => ({ json: a }));

// ─────────────────────────────────────────────────────────────
// PICK TOP N *UNIQUE* CREATIVES FOR THE AI
// The same video often runs under several ad IDs (DCO, A/B copies,
// language variants of the caption). Sending it to the model twice
// wastes free-tier quota and gives no new information, so we skip
// any ad whose creative was already picked.
// ─────────────────────────────────────────────────────────────
const n = Number($('Config').first().json.analyzeTopN) || 8;
const seen = new Set();
const picked = [];
for (const item of $input.all()) {
  const key = item.json.creativeKey;
  if (seen.has(key)) continue;
  seen.add(key);
  picked.push({ json: item.json });
  if (picked.length >= n) break;
}
return picked;

// ─────────────────────────────────────────────────────────────
// BUILD GEMINI REQUEST (one ad per loop iteration)
// Video ads → the whole MP4 goes to Gemini, which reads the frames AND
// hears the audio. That matters: in a talking-head / skit ad the hook
// is what is SAID in the first 3 seconds, not the thumbnail.
// Degrades gracefully: video too big or failed → preview frame →
// copy only. The source used is recorded on every row.
// ─────────────────────────────────────────────────────────────
const ad = $('Loop Over Items').first().json;
const cfg = $('Config').first().json;
const input = $input.first();
const maxBytes = (Number(cfg.maxCreativeMB) || 14) * 1024 * 1024;
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36';

let media = null;      // { inline_data: { mime_type, data } }
let source = 'copy only';
let mediaIssue = '';

// 1) whatever "Download Creative" fetched (the video for video ads)
try {
  if (input.binary && input.binary.data) {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    const mime = String(input.binary.data.mimeType || '').split(';')[0].trim().toLowerCase();
    const isVideo = mime.startsWith('video/') || (ad.mediaType === 'video' && !mime.startsWith('image/'));
    if (!buf.length) {
      mediaIssue = 'download was empty';
    } else if (buf.length > maxBytes) {
      mediaIssue = `creative is ${(buf.length / 1048576).toFixed(1)} MB (limit ${cfg.maxCreativeMB || 14} MB)`;
    } else if (isVideo) {
      media = { inline_data: { mime_type: mime.startsWith('video/') ? mime : 'video/mp4', data: buf.toString('base64') } };
      source = 'full video (frames + audio) + copy';
    } else {
      media = { inline_data: { mime_type: mime.startsWith('image/') ? mime : 'image/jpeg', data: buf.toString('base64') } };
      source = 'image + copy';
    }
  } else {
    const err = input.json && input.json.error;
    mediaIssue = err ? `download failed: ${typeof err === 'string' ? err : err.message || 'error'}` : 'no creative URL';
  }
} catch (e) {
  mediaIssue = `could not read download: ${e.message}`;
}

// 2) video unusable → fall back to its preview frame
if (!media && ad.mediaType === 'video' && ad.imageUrl) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET', url: ad.imageUrl, encoding: 'arraybuffer', returnFullResponse: true,
      headers: { 'User-Agent': UA }, timeout: 30000,
    });
    const buf = Buffer.from(res.body);
    const mime = String((res.headers && res.headers['content-type']) || 'image/jpeg').split(';')[0];
    if (buf.length && buf.length <= maxBytes) {
      media = { inline_data: { mime_type: mime.startsWith('image/') ? mime : 'image/jpeg', data: buf.toString('base64') } };
      source = 'video preview frame + copy';
    }
  } catch (e) {
    mediaIssue += ' · preview frame also failed';
  }
}

const mediaNote = source.startsWith('full video')
  ? `The attached file is the full ${ad.videoDurationSec ? ad.videoDurationSec + '-second ' : ''}video ad. Watch AND listen to it. Use timestamps in seconds.`
  : source === 'video preview frame + copy'
    ? `This is a VIDEO ad but only its preview frame could be attached (${mediaIssue}). You cannot hear the audio: base the hook on the frame + headline + first line of copy, leave spoken fields as "none", and say so in "notes".`
    : source === 'image + copy'
      ? 'The attached image is the ad creative.'
      : `No creative could be attached (${mediaIssue || 'none available'}). Analyse the text only and say so in "notes".`;

const prompt = `You are a performance-marketing creative analyst for ${cfg.brandName}, ${cfg.brandContext}

Break this ad down into HOOK → BODY → CTA. ${mediaNote}

Ad facts from the Ad Library (do not contradict these):
- Page: ${ad.pageName}
- Caption language (detected): ${ad.language}
- Headline: ${ad.headline || 'none'}
- Primary text (caption): ${ad.primaryText || 'none'}
- CTA button: ${ad.ctaButton || 'none'}
- Store: ${ad.store}

Definitions:
- HOOK = the first ~3 seconds (or the first thing seen on a static ad): what is said, what text is on screen, what is shown.
- BODY = everything between the hook and the call to action: the beats that build desire and belief.
- CTA = the moment the viewer is told what to do (spoken and/or on screen), plus the offer and any urgency.

Rules:
- Judge ONLY the creative. You are not told how long it ran or how many impressions it got, on purpose.
- Quote spoken words in their original language and script, then translate.
- Be strict with scores: 9-10 must be rare. No generic praise ("engaging", "catchy") — be specific to this ad.
- If something is not present write "none". Never invent words that are not said or shown.`;

// Structured output: Gemini is forced to return exactly this shape.
const S = (description) => ({ type: 'STRING', description });
const schema = {
  type: 'OBJECT',
  properties: {
    spoken_language: S('language(s) spoken in the ad, e.g. "Hindi + English"; "none" if no speech'),
    hook: {
      type: 'OBJECT',
      properties: {
        ends_at_sec: { type: 'NUMBER', description: 'second where the hook ends (0 for static ads)' },
        spoken_original: S('words spoken in the hook, original language/script, or "none"'),
        spoken_english: S('English translation of the spoken hook, or "none"'),
        on_screen_text: S('text shown on screen during the hook, or "none"'),
        visual: S('what the viewer sees in the hook'),
        type: { type: 'STRING', enum: ['pain_point', 'relatable_scenario', 'curiosity_question', 'social_proof', 'price_offer', 'transformation', 'fear_of_judgement', 'demo', 'authority', 'other'] },
        why_it_stops_the_scroll: S('one specific sentence'),
      },
      required: ['spoken_original', 'spoken_english', 'on_screen_text', 'visual', 'type', 'why_it_stops_the_scroll'],
    },
    body: {
      type: 'OBJECT',
      properties: {
        beats: {
          type: 'ARRAY',
          description: '3-6 beats in order',
          items: { type: 'OBJECT', properties: { at_sec: { type: 'NUMBER' }, what_happens: S('short') }, required: ['what_happens'] },
        },
        summary: S('2 sentences: how the body builds desire after the hook'),
        key_claims: { type: 'ARRAY', items: { type: 'STRING' }, description: 'max 3' },
        proof: S('proof used (numbers, app demo, testimonial, before/after) or "none"'),
        shows_app: { type: 'BOOLEAN', description: 'is the app UI shown?' },
      },
      required: ['beats', 'summary', 'key_claims', 'proof', 'shows_app'],
    },
    cta: {
      type: 'OBJECT',
      properties: {
        at_sec: { type: 'NUMBER' },
        spoken_or_onscreen: S('the CTA as said/shown, original language + English, or "none"'),
        offer: S('e.g. "₹1 trial", or "none"'),
        urgency: S('urgency/scarcity used, or "none"'),
      },
      required: ['spoken_or_onscreen', 'offer', 'urgency'],
    },
    format: { type: 'STRING', enum: ['ugc_talking_head', 'skit', 'app_screen_demo', 'animation', 'testimonial', 'street_interview', 'slideshow', 'static_image', 'other'] },
    angle: S('core persuasion angle in under 10 words'),
    target_persona: S('who this ad is for, one short sentence'),
    scores: {
      type: 'OBJECT',
      properties: {
        hook_strength: { type: 'INTEGER', description: '1-10' },
        clarity: { type: 'INTEGER', description: '1-10' },
        offer_clarity: { type: 'INTEGER', description: '1-10' },
        cultural_fit: { type: 'INTEGER', description: '1-10' },
      },
      required: ['hook_strength', 'clarity', 'offer_clarity', 'cultural_fit'],
    },
    why_it_works: S('1-2 sentences specific to this creative'),
    weakness: S('the single biggest weakness, specific'),
    notes: S('caveats, e.g. what could not be checked'),
  },
  required: ['spoken_language', 'hook', 'body', 'cta', 'format', 'angle', 'target_persona', 'scores', 'why_it_works', 'weakness', 'notes'],
};

const parts = [];
if (media) parts.push(media); // media before text, as Google recommends
parts.push({ text: prompt });

return [{
  json: {
    adId: ad.adId,
    source,
    mediaIssue,
    model: cfg.aiModel,
    fallbackModel: cfg.fallbackModel,
    geminiBody: {
      contents: [{ role: 'user', parts }],
      generationConfig: { responseMimeType: 'application/json', responseSchema: schema, maxOutputTokens: 8192 },
    },
  },
}];

// ─────────────────────────────────────────────────────────────
// PARSE GEMINI RESPONSE → flat fields merged back onto the ad
// Receives output from either the primary or the fallback model node.
// Never throws: a failed ad is kept with aiError filled in, so one bad
// video can't kill the whole run.
// ─────────────────────────────────────────────────────────────
const ad = $('Loop Over Items').first().json;
const req = $('Build Gemini Request').first().json;
const res = $input.first().json || {};

function errText(r) {
  const e = r.error;
  if (!e) return '';
  if (typeof e === 'string') return e;
  return e.message || e.description || JSON.stringify(e).slice(0, 300);
}

let a = null;
let aiError = '';
try {
  const cand = res.candidates && res.candidates[0];
  const text = ((cand && cand.content && cand.content.parts) || [])
    .filter((p) => typeof p.text === 'string' && !p.thought)
    .map((p) => p.text)
    .join('');
  if (!text) throw new Error(cand && cand.finishReason ? `model stopped: ${cand.finishReason}` : 'empty response');
  const s = text.indexOf('{');
  const e = text.lastIndexOf('}');
  a = JSON.parse(text.slice(s, e + 1));
} catch (err) {
  aiError = errText(res) || (res.promptFeedback && res.promptFeedback.blockReason ? `blocked: ${res.promptFeedback.blockReason}` : '') || err.message;
}

const none = (v) => (v == null || /^none$/i.test(String(v).trim()) ? '' : String(v).trim());
const hook = (a && a.hook) || {};
const body = (a && a.body) || {};
const cta = (a && a.cta) || {};
const sc = (a && a.scores) || {};
const vals = ['hook_strength', 'clarity', 'offer_clarity', 'cultural_fit']
  .map((k) => Number(sc[k]))
  .filter((n) => n >= 1 && n <= 10);
const creativeScore = vals.length ? Math.round((vals.reduce((p, c) => p + c, 0) / vals.length) * 10) : null;
const beats = Array.isArray(body.beats)
  ? body.beats.map((b) => `${b.at_sec != null ? b.at_sec + 's: ' : ''}${b.what_happens}`).join(' → ')
  : '';

return [{
  json: {
    ...ad,
    aiAnalysed: !!a,
    analysedFrom: a ? req.source : 'failed',
    modelUsed: res.modelVersion || '',
    aiError,
    spokenLanguage: none(a && a.spoken_language),
    hookSpoken: none(hook.spoken_original),
    hookEnglish: none(hook.spoken_english),
    hookOnScreen: none(hook.on_screen_text),
    hookVisual: none(hook.visual),
    hookType: hook.type || '',
    hookEndsAt: hook.ends_at_sec ?? null,
    hookWhy: none(hook.why_it_stops_the_scroll),
    bodyBeats: beats,
    bodySummary: none(body.summary),
    keyClaims: Array.isArray(body.key_claims) ? body.key_claims.join(' | ') : '',
    proof: none(body.proof),
    showsApp: body.shows_app ?? null,
    ctaInCreative: none(cta.spoken_or_onscreen),
    ctaAt: cta.at_sec ?? null,
    offer: none(cta.offer),
    urgency: none(cta.urgency),
    creativeFormat: (a && a.format) || '',
    angle: none(a && a.angle),
    targetPersona: none(a && a.target_persona),
    hookStrength: sc.hook_strength ?? null,
    clarity: sc.clarity ?? null,
    offerClarity: sc.offer_clarity ?? null,
    culturalFit: sc.cultural_fit ?? null,
    creativeScore,
    whyItWorks: none(a && a.why_it_works),
    weakness: none(a && a.weakness),
    aiNotes: none(a && a.notes),
  },
}];

// ─────────────────────────────────────────────────────────────
// RANK & PICK THE BEST AD
// finalScore = performanceWeight × performanceScore (market evidence)
//            + (1 − performanceWeight) × creativeScore (AI judgement)
// Evidence is weighted higher than AI opinion on purpose: Meta's
// delivery algorithm has already "voted" with real money.
// ─────────────────────────────────────────────────────────────
const cfg = $('Config').first().json;
const w = Math.min(1, Math.max(0, Number(cfg.performanceWeight ?? 0.6)));

const all = $('Clean & Score Ads').all().map((i) => i.json);
const byId = {};
for (const it of $input.all()) byId[it.json.adId] = it.json;

const merged = all.map((ad) => byId[ad.adId] || {
  ...ad, aiAnalysed: false, creativeScore: null,
  analysedFrom: 'not analysed (outside top N or duplicate creative)',
});
for (const r of merged) {
  r.finalScore = r.creativeScore == null ? null : Math.round(w * r.performanceScore + (1 - w) * r.creativeScore);
}
merged.sort((a, b) => (b.finalScore ?? -1) - (a.finalScore ?? -1) || b.performanceScore - a.performanceScore);
const best = merged.find((r) => r.finalScore != null);

return merged.map((r, i) => ({
  json: {
    final_rank: i + 1,
    best_ad: r === best ? '★ BEST' : '',
    ad_id: r.adId,
    ad_library_link: r.adLibraryLink,
    page: r.pageName,
    language: r.spokenLanguage || r.language,
    caption_language: r.language,
    concept: r.conceptLabel,
    headline: r.headline,
    impression_rank: r.impressionRank,
    days_active: r.daysActive,
    maturity: r.maturity,
    start_date: r.startDate,
    ads_in_concept: r.adsInConcept,
    meta_versions: r.collationCount,
    creative_variants: r.creativeVariants,
    media_type: r.mediaType,
    video_sec: r.videoDurationSec,
    performance_score: r.performanceScore,
    creative_score: r.creativeScore,
    final_score: r.finalScore,
    hook_spoken: r.hookSpoken || '',
    hook_english: r.hookEnglish || '',
    hook_on_screen: r.hookOnScreen || '',
    hook_visual: r.hookVisual || '',
    hook_type: r.hookType || '',
    hook_why: r.hookWhy || '',
    body_beats: r.bodyBeats || '',
    body_summary: r.bodySummary || '',
    key_claims: r.keyClaims || '',
    proof: r.proof || '',
    cta_in_creative: r.ctaInCreative || '',
    cta_button: r.ctaButton,
    offer: r.offer || '',
    urgency: r.urgency || '',
    format: r.creativeFormat || '',
    angle: r.angle || '',
    target_persona: r.targetPersona || '',
    hook_strength: r.hookStrength ?? null,
    clarity: r.clarity ?? null,
    offer_clarity: r.offerClarity ?? null,
    cultural_fit: r.culturalFit ?? null,
    why_it_works: r.whyItWorks || '',
    weakness: r.weakness || '',
    copy_hook: r.copyHook,
    primary_text: r.primaryText,
    store: r.store,
    platforms: r.platforms,
    thumbnail_url: r.imageUrl || '',
    analysed_from: r.analysedFrom,
    model_used: r.modelUsed || '',
    ai_notes: r.aiNotes || '',
    ai_error: r.aiError || '',
  },
}));

// ─────────────────────────────────────────────────────────────
// BUILD INSIGHTS PROMPT (one call for the whole report)
// ─────────────────────────────────────────────────────────────
const cfg = $('Config').first().json;
const rows = $input.all().map((i) => i.json);
const analysed = rows.filter((r) => r.final_score != null);

const compact = analysed.map((r) => ({
  final_rank: r.final_rank,
  ad_id: r.ad_id,
  language: r.language,
  impression_rank: r.impression_rank,
  days_active: r.days_active,
  maturity: r.maturity,
  ads_in_concept: r.ads_in_concept,
  meta_versions: r.meta_versions,
  video_sec: r.video_sec,
  performance_score: r.performance_score,
  creative_score: r.creative_score,
  final_score: r.final_score,
  analysed_from: r.analysed_from,
  hook_spoken: r.hook_spoken,
  hook_english: r.hook_english,
  hook_on_screen: r.hook_on_screen,
  hook_visual: r.hook_visual,
  hook_type: r.hook_type,
  body_beats: r.body_beats,
  proof: r.proof,
  cta_in_creative: r.cta_in_creative,
  offer: r.offer,
  format: r.format,
  angle: r.angle,
  why_it_works: r.why_it_works,
  weakness: r.weakness,
}));

// coverage of ALL scraped ads (not just analysed ones)
const coverage = {};
for (const r of rows) {
  const k = r.caption_language || r.language;
  const c = (coverage[k] = coverage[k] || { ads: 0, best_impression_rank: 999, longest_days_active: 0 });
  c.ads += 1;
  c.best_impression_rank = Math.min(c.best_impression_rank, r.impression_rank);
  c.longest_days_active = Math.max(c.longest_days_active, r.days_active);
}

const prompt = `You are the head of growth creative at ${cfg.brandName}, ${cfg.brandContext}
An automated pipeline scraped ${cfg.brandName}'s ACTIVE Meta ads (the Ad Library search in Config) and had Gemini watch and listen to the top ones.

How the numbers were built (use this to reason, do not repeat it at length):
- impression_rank: position in the Ad Library sorted by total impressions (1 = most impressions).
- days_active / maturity: how long the ad has survived. Losing ads get switched off quickly. "new (unproven)" < 7 days, "scaling" < 30, "proven" ≥ 30.
- ads_in_concept / meta_versions: how many live ads reuse this copy / how many versions Meta groups under it → the team is scaling it.
- performance_score (0-100) = 50% impression rank + 35% longevity (capped at ${cfg.longevityCapDays || 90} days) + 15% scale.
- creative_score (0-100) = Gemini's BLIND rating of the creative (it was not shown any performance numbers).
- final_score = ${Math.round((cfg.performanceWeight ?? 0.6) * 100)}% performance_score + ${Math.round((1 - (cfg.performanceWeight ?? 0.6)) * 100)}% creative_score.
- analysed_from says whether the model saw the full video with audio, only a frame, or only the caption. Weight conclusions accordingly.

ANALYSED ADS:
${JSON.stringify(compact, null, 1)}

LANGUAGE COVERAGE (by caption) ACROSS ALL ${rows.length} SCRAPED ADS:
${JSON.stringify(coverage, null, 1)}

Write a sharp report in Markdown with exactly these sections (use ## headings):
## Why this is the best ad
Name the ad_id, quote its hook (original + English), and justify the pick with its numbers. Say clearly whether it is a new ad with high impressions but unproven, or an old proven ad that may be fatiguing. Name the runner-up and why it lost.
## Winning patterns
3-5 bullets. Each bullet names the ad_ids that show it.
## Where the weaker ads lose
2-3 bullets, each naming ad_ids.
## Where performance and creative quality disagree
Any ad Meta is spending on that the model rated weak (or vice versa) and what that suggests.
## Gaps & opportunities
Languages, angles or formats ${cfg.brandName} is not using yet, based on the coverage data.
## 3 new ad scripts
Built on the winning pattern. For each: target language, 0-3s hook (original language + English), body beats (3 bullets), CTA, format, and which winning ad it is modelled on.
## 2 A/B tests for next week
Hypothesis, what changes, success metric (e.g. CTR, cost per install, 3-second view rate).

Rules: only use numbers that appear in the data above. No generic advice such as "use a strong hook". Under 800 words. Do not add a title.`;

return [{
  json: {
    model: cfg.reportModel,
    fallbackModel: cfg.fallbackModel,
    geminiBody: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { maxOutputTokens: 8192 },
    },
    analysedCount: analysed.length,
    totalAds: rows.length,
  },
}];

// ─────────────────────────────────────────────────────────────
// FORMAT FINAL REPORT (Markdown)
// The per-ad Hook / Body / CTA breakdown is built straight from the
// structured data — not re-written by the LLM — so what's in the PDF
// is exactly what was extracted.
// ─────────────────────────────────────────────────────────────
const cfg = $('Config').first().json;
const meta = $('Build Insights Prompt').first().json;
const rows = $('Rank & Pick Best').all().map((i) => i.json);
const res = $input.first().json || {};

const cand = res.candidates && res.candidates[0];
const aiText = ((cand && cand.content && cand.content.parts) || [])
  .filter((p) => typeof p.text === 'string' && !p.thought).map((p) => p.text).join('').trim();
const errMsg = res.error ? (typeof res.error === 'string' ? res.error : res.error.message || JSON.stringify(res.error)) : 'no response';
const insights = aiText || `_AI insights failed (${errMsg}). The scored table and the ad-by-ad breakdown below are still complete._`;

const esc = (s) => String(s ?? '').replace(/\|/g, '/').replace(/\s+/g, ' ').trim();
const analysed = rows.filter((r) => r.final_score != null);
const best = analysed[0];

const table = [
  '| # | Ad | Language | Impr. rank | Days live | Perf. | Creative | **Final** | Hook (EN) |',
  '|---|---|---|---|---|---|---|---|---|',
  ...analysed.map((r) => `| ${r.final_rank}${r.best_ad ? ' ★' : ''} | [${r.ad_id}](${r.ad_library_link}) | ${esc(r.language)} | ${r.impression_rank} | ${r.days_active} | ${r.performance_score} | ${r.creative_score} | **${r.final_score}** | ${esc(r.hook_english || r.hook_on_screen || r.copy_hook).slice(0, 90)} |`),
].join('\n');

const bestCard = best ? [
  `## ★ Winner at a glance: [${best.ad_id}](${best.ad_library_link})`,
  best.thumbnail_url ? `![Best ad preview](${best.thumbnail_url})` : '',
  `**Final score ${best.final_score}** (performance ${best.performance_score}, creative ${best.creative_score}) · impression rank #${best.impression_rank} · live ${best.days_active} days (${best.maturity}) · ${esc(best.format)} · ${esc(best.language)}`,
  '',
  `- **Hook:** ${esc(best.hook_spoken || best.hook_on_screen) || '—'}${best.hook_english ? ` — _"${esc(best.hook_english)}"_` : ''}`,
  `- **Body:** ${esc(best.body_summary) || '—'}`,
  `- **CTA:** ${esc(best.cta_in_creative) || esc(best.cta_button) || '—'}${best.offer ? ` · offer: ${esc(best.offer)}` : ''}`,
].filter(Boolean).join('\n') : '## Best ad\n_No ad could be analysed by the AI in this run — see ai_error in the sheet._';

const perAd = analysed.map((r) => [
  `### ${r.final_rank}. [${r.ad_id}](${r.ad_library_link})${r.best_ad ? ' ★' : ''}`,
  `${esc(r.language)} · ${esc(r.format) || r.media_type}${r.video_sec ? ` · ${r.video_sec}s` : ''} · impression rank #${r.impression_rank} · ${r.days_active} days live · final ${r.final_score} · _analysed from: ${r.analysed_from}_`,
  '',
  `**HOOK** (${esc(r.hook_type) || '—'})`,
  r.hook_spoken ? `- Said: ${esc(r.hook_spoken)}${r.hook_english ? ` — _"${esc(r.hook_english)}"_` : ''}` : null,
  r.hook_on_screen ? `- On screen: ${esc(r.hook_on_screen)}` : null,
  r.hook_visual ? `- Shows: ${esc(r.hook_visual)}` : null,
  r.hook_why ? `- Why it stops the scroll: ${esc(r.hook_why)}` : null,
  '',
  '**BODY**',
  r.body_beats ? `- Beats: ${esc(r.body_beats)}` : null,
  r.body_summary ? `- ${esc(r.body_summary)}` : null,
  r.proof ? `- Proof: ${esc(r.proof)}` : null,
  '',
  '**CTA**',
  `- ${esc(r.cta_in_creative) || 'none in creative'} · button: ${esc(r.cta_button) || '—'}${r.offer ? ` · offer: ${esc(r.offer)}` : ''}${r.urgency ? ` · urgency: ${esc(r.urgency)}` : ''}`,
  '',
  `**Works because:** ${esc(r.why_it_works) || '—'}  `,
  `**Weakness:** ${esc(r.weakness) || '—'}`,
].filter((l) => l !== null).join('\n')).join('\n\n---\n\n');

const failed = rows.filter((r) => r.ai_error);
const failNote = failed.length ? `\n\n> ${failed.length} ad(s) could not be analysed: ${failed.map((r) => `${r.ad_id} (${esc(r.ai_error).slice(0, 80)})`).join('; ')}` : '';

const w = Number(cfg.performanceWeight ?? 0.6);
const report = `# ${cfg.brandName} – Meta Ad Library Analysis
Run ${new Date().toISOString().slice(0, 16).replace('T', ' ')} UTC · India · active ads · ${meta.totalAds} ads scraped · ${meta.analysedCount} unique creatives analysed by ${cfg.aiModel} · [Source Ad Library search](${cfg.adLibraryUrl})

${bestCard}

## Leaderboard
_Final = ${Math.round(w * 100)}% performance (impression rank 50% · days live 35% · scale 15%) + ${Math.round((1 - w) * 100)}% creative score (Gemini, blind to performance)._

${table}${failNote}

${insights}

## Ad-by-ad breakdown: Hook → Body → CTA

${perAd}
`;

return [{ json: { report } }];

